-- ---------------------------------------------------------------------------
-- 176  Hyjal round-43 -- replace the Azshara corner's content with Cataclysm's
-- ---------------------------------------------------------------------------
-- TERRAIN NEEDS NO WORK.  Heightmap comparison against a fresh retail bake
-- proved the nine shipped Azshara tiles are ALREADY the post-Cataclysm terrain
-- (identical MCVT hashes on every sampled tile) -- the earlier note claiming
-- this corner was stock WotLK was wrong; the whole map is one retail bake.
--
-- What was wrong is the CONTENT: 164_/166_ imported the stock-WotLK spawn
-- layer by coordinates, so pre-Cata NPCs stand on post-Cata ground.  This file
-- swaps that layer for cata_world's Azshara content (the ~11% of the zone that
-- falls inside the terrain box; the rest of Cata Azshara -- Bilgewater Harbor,
-- the south -- lies beyond the map edge).
--
-- PRECISION: the wipe is scoped by a CHUNK MASK, not a box.  Every terrain
-- chunk tagged 4930 in the nine Azshara tiles contributes one 33.3x33.3-yd
-- world rect (read straight out of the shipped ADTs).  A bounding box CANNOT
-- express this region: Winterspring's Darkwhisper corner and Hyjal's eastern
-- slopes overlap any rectangle drawn around Azshara, and a box wipe would
-- delete their spawns too.
--
-- IMPORT: the original Cata port series (01/02/04/07/08/09/12) re-run with the
-- id set swapped from Hyjal (zoneId=616) to box-limited Azshara (zoneId=16).
-- Same statements, same +3,600,000 convention, same INSERT IGNORE dedup --
-- entries already cloned for Hyjal are reused, not duplicated.  Spawn guids
-- are auto-assigned (the 04_ convention), which also keeps them OUTSIDE
-- 166_'s 15.6-15.9M source range, so a 166_ re-run cannot re-clone them.
--
-- KEPT DELIBERATELY: Kroum (guid 15810001) and taxi node 338 at Valormok.
-- Cata retired that flight point (Bilgewater replaced it, far off-map), but
-- removing a node from the 12-node full-mesh taxi network is its own change
-- with client DBC edits -- flagged for a follow-up decision, not smuggled in.
--
-- Quests are NOT ported here (phase 2, mirrors 11_/50_) -- cloned NPCs offer
-- what their template carries; the Azshara quest layer needs its own pass.
--
-- Idempotent: the wipe also clears any previous cata-azshara import
-- (map 750 spawns with id >= 3,600,000 inside the mask) before re-importing.
-- ---------------------------------------------------------------------------

SET @OFF := 3600000;

DROP TABLE IF EXISTS `_dc_az_mask`;
CREATE TABLE `_dc_az_mask` (
  `xmin` FLOAT NOT NULL, `xmax` FLOAT NOT NULL,
  `ymin` FLOAT NOT NULL, `ymax` FLOAT NOT NULL
) ENGINE=InnoDB;



-- --- wipe: stock-WotLK layer + any prior cata import, inside the mask -------
DELETE FROM `creature_addon`
WHERE `guid` IN (SELECT `guid` FROM (
  SELECT c.`guid` FROM `creature` c
  WHERE c.`map` = 750
    AND (c.`guid` BETWEEN 15600000 AND 15899999 OR c.`id` >= @OFF)
    AND c.`guid` <> 15810001
    AND EXISTS (SELECT 1 FROM `_dc_az_mask` m
                WHERE c.`position_x` > m.`xmin` AND c.`position_x` <= m.`xmax`
                  AND c.`position_y` > m.`ymin` AND c.`position_y` <= m.`ymax`)) t);

DELETE FROM `creature`
WHERE `map` = 750
  AND (`guid` BETWEEN 15600000 AND 15899999 OR `id` >= @OFF)
  AND `guid` <> 15810001
  AND EXISTS (SELECT 1 FROM `_dc_az_mask` m
              WHERE `position_x` > m.`xmin` AND `position_x` <= m.`xmax`
                AND `position_y` > m.`ymin` AND `position_y` <= m.`ymax`);

DELETE FROM `gameobject`
WHERE `map` = 750
  AND (`guid` BETWEEN 15600000 AND 15899999 OR `id` >= @OFF)
  AND EXISTS (SELECT 1 FROM `_dc_az_mask` m
              WHERE `position_x` > m.`xmin` AND `position_x` <= m.`xmax`
                AND `position_y` > m.`ymin` AND `position_y` <= m.`ymax`);


-- --- creature templates (+model/addon/movement)  (adapted from 01_creature_templates.sql) ---
SELECT `entry`+@OFF, `difficulty_entry_1`, `difficulty_entry_2`, `difficulty_entry_3`, `KillCredit1`, `KillCredit2`, `name`, `subname`, `IconName`, `gossip_menu_id`, `minlevel`, `maxlevel`, `faction`, `npcflag`, `speed_walk`, `speed_run`, `rank`, `dmgschool`, `DamageModifier`, `BaseAttackTime`, `RangeAttackTime`, `BaseVariance`, `RangeVariance`, `unit_class`, `unit_flags`, `unit_flags2`, `family`, `type`, `type_flags`, `lootid`, `pickpocketloot`, `skinloot`, `PetSpellDataId`, `VehicleId`, `mingold`, `maxgold`, `AIName`, `MovementType`, `HoverHeight`, `HealthModifier`, `ManaModifier`, `ArmorModifier`, `ExperienceModifier`, `RacialLeader`, `movementId`, `RegenHealth`, `flags_extra`, `ScriptName`, `VerifiedBuild` FROM cata_world.creature_template
WHERE entry IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200)) AND entry NOT IN (SELECT entry FROM acore_world.creature_template WHERE entry < @OFF);

SELECT `entry`+@OFF, `difficulty_entry_1`, `difficulty_entry_2`, `difficulty_entry_3`, `KillCredit1`, `KillCredit2`, `name`, `subname`, `IconName`, `gossip_menu_id`, `minlevel`, `maxlevel`, `exp`, `faction`, `npcflag`, `speed_walk`, `speed_run`, `speed_swim`, `speed_flight`, `detection_range`, `rank`, `dmgschool`, `DamageModifier`, `BaseAttackTime`, `RangeAttackTime`, `BaseVariance`, `RangeVariance`, `unit_class`, `unit_flags`, `unit_flags2`, `dynamicflags`, `family`, `type`, `type_flags`, `lootid`, `pickpocketloot`, `skinloot`, `PetSpellDataId`, `VehicleId`, `mingold`, `maxgold`, `AIName`, `MovementType`, `HoverHeight`, `HealthModifier`, `ManaModifier`, `ArmorModifier`, `ExperienceModifier`, `RacialLeader`, `movementId`, `RegenHealth`, `CreatureImmunitiesId`, `flags_extra`, `ScriptName`, `VerifiedBuild` FROM acore_world.creature_template
WHERE entry IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200)) AND entry < @OFF;

SELECT `CreatureID`+@OFF, `Idx`, `CreatureDisplayID`, `Probability`, `VerifiedBuild` FROM cata_world.creature_template_model WHERE CreatureID IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200));

SELECT `entry`+@OFF, `mount`, `emote`, `visibilityDistanceType`, `auras` FROM cata_world.creature_template_addon WHERE entry IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200)) AND entry NOT IN (SELECT entry FROM acore_world.creature_template WHERE entry < @OFF);
SELECT `entry`+@OFF, `mount`, `emote`, `visibilityDistanceType`, `auras` FROM acore_world.creature_template_addon WHERE entry IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200)) AND entry IN (SELECT entry FROM acore_world.creature_template WHERE entry < @OFF) AND entry < @OFF;

SELECT cl.`entry`, sm.`Ground`, sm.`Swim`, sm.`Flight`, sm.`Rooted`, sm.`Chase`, sm.`Random`, sm.`InteractionPauseTimer`
FROM acore_world.creature_template cl
JOIN acore_world.creature_template_movement sm ON sm.CreatureId = cl.entry - @OFF
WHERE cl.entry IN (SELECT entry+@OFF FROM cata_world.creature_template WHERE entry IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200)));
SELECT n.entry+@OFF, (n.InhabitType & 1), ((n.InhabitType >> 3) & 1), 1, 0, 0, 0, 0
FROM nelt_world.creature_template n
WHERE n.entry IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200))
  AND n.InhabitType IN (4,5,6,7);


-- --- gameobject templates  (adapted from 02_gameobject_templates.sql) ---
SELECT `entry`+@OFF, `type`, `displayId`, `name`, `IconName`, `castBarCaption`, `unk1`, `size`, `Data0`, `Data1`, `Data2`, `Data3`, `Data4`, `Data5`, `Data6`, `Data7`, `Data8`, `Data9`, `Data10`, `Data11`, `Data12`, `Data13`, `Data14`, `Data15`, `Data16`, `Data17`, `Data18`, `Data19`, `Data20`, `Data21`, `Data22`, `Data23`, `AIName`, `ScriptName`, `VerifiedBuild` FROM cata_world.gameobject_template WHERE entry IN (SELECT DISTINCT g.id FROM cata_world.gameobject g WHERE (g.map=1 AND g.zoneId=16 AND g.position_x BETWEEN 3200 AND 5400 AND g.position_y BETWEEN -5334 AND -3200)) AND entry NOT IN (SELECT entry FROM acore_world.gameobject_template WHERE entry < @OFF);
SELECT `entry`+@OFF, `type`, `displayId`, `name`, `IconName`, `castBarCaption`, `unk1`, `size`, `Data0`, `Data1`, `Data2`, `Data3`, `Data4`, `Data5`, `Data6`, `Data7`, `Data8`, `Data9`, `Data10`, `Data11`, `Data12`, `Data13`, `Data14`, `Data15`, `Data16`, `Data17`, `Data18`, `Data19`, `Data20`, `Data21`, `Data22`, `Data23`, `AIName`, `ScriptName`, `VerifiedBuild` FROM acore_world.gameobject_template WHERE entry IN (SELECT DISTINCT g.id FROM cata_world.gameobject g WHERE (g.map=1 AND g.zoneId=16 AND g.position_x BETWEEN 3200 AND 5400 AND g.position_y BETWEEN -5334 AND -3200)) AND entry < @OFF;
SELECT `entry`+@OFF, `faction`, `flags`, `mingold`, `maxgold`, `artkit0`, `artkit1`, `artkit2`, `artkit3` FROM cata_world.gameobject_template_addon WHERE entry IN (SELECT DISTINCT g.id FROM cata_world.gameobject g WHERE (g.map=1 AND g.zoneId=16 AND g.position_x BETWEEN 3200 AND 5400 AND g.position_y BETWEEN -5334 AND -3200)) AND entry NOT IN (SELECT entry FROM acore_world.gameobject_template WHERE entry < @OFF);
SELECT `entry`+@OFF, `faction`, `flags`, `mingold`, `maxgold`, `artkit0`, `artkit1`, `artkit2`, `artkit3` FROM acore_world.gameobject_template_addon WHERE entry IN (SELECT DISTINCT g.id FROM cata_world.gameobject g WHERE (g.map=1 AND g.zoneId=16 AND g.position_x BETWEEN 3200 AND 5400 AND g.position_y BETWEEN -5334 AND -3200)) AND entry IN (SELECT entry FROM acore_world.gameobject_template WHERE entry < @OFF) AND entry < @OFF;


-- --- spawns (zone tag corrected to 4930 below)  (adapted from 04_spawns.sql) ---
SELECT c.`id`+@OFF, 750, 4930, 4930, c.`spawnMask`, c.`phaseMask`, c.`equipment_id`, c.`position_x`, c.`position_y`, c.`position_z`, c.`orientation`, c.`spawntimesecs`, c.`wander_distance`, c.`currentwaypoint`, COALESCE(c.`curhealth`,1), COALESCE(c.`curmana`,0), c.`MovementType`, COALESCE(c.`npcflag`,0), COALESCE(c.`unit_flags`,0)
FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200);

SELECT g.`id`+@OFF, 750, 4930, 4930, g.`spawnMask`, g.`phaseMask`, g.`position_x`, g.`position_y`, g.`position_z`, g.`orientation`, g.`rotation0`, g.`rotation1`, g.`rotation2`, g.`rotation3`, g.`spawntimesecs`, g.`animprogress`, g.`state`
FROM cata_world.gameobject g WHERE (g.map=1 AND g.zoneId=16 AND g.position_x BETWEEN 3200 AND 5400 AND g.position_y BETWEEN -5334 AND -3200);


-- --- creature text  (adapted from 07_creature_text.sql) ---
SELECT `CreatureID`+@OFF, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment` FROM cata_world.creature_text WHERE CreatureID IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200)) AND CreatureID NOT IN (SELECT entry FROM acore_world.creature_template WHERE entry < @OFF);
SELECT `CreatureID`+@OFF, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment` FROM acore_world.creature_text WHERE CreatureID IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200)) AND CreatureID IN (SELECT entry FROM acore_world.creature_template WHERE entry < @OFF) AND CreatureID < @OFF;


-- --- loot  (adapted from 08_loot.sql) ---
SELECT lt.`Entry`, lt.`Item`, lt.`Reference`, lt.`Chance`, lt.`QuestRequired`, lt.`LootMode`, lt.`GroupId`, lt.`MinCount`, lt.`MaxCount`, lt.`Comment`
FROM (
  SELECT DISTINCT ct.lootid AS lootid
  FROM cata_world.creature_template ct
  JOIN cata_world.creature c ON c.id = ct.entry
  LEFT JOIN acore_world.creature_template ac ON ac.entry = ct.entry AND ac.entry < @OFF
  WHERE ct.lootid > 0 AND (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200) AND ac.entry IS NULL
) L
JOIN cata_world.creature_loot_template lt ON lt.Entry = L.lootid;


-- --- gossip  (adapted from 09_gossip.sql) ---
SELECT gm.MenuID, gm.TextID FROM cata_world.gossip_menu gm
JOIN (SELECT DISTINCT ct.gossip_menu_id AS mid
  FROM cata_world.creature_template ct
  JOIN cata_world.creature c ON c.id = ct.entry
  LEFT JOIN acore_world.creature_template ac ON ac.entry = ct.entry AND ac.entry < @OFF
  WHERE ct.gossip_menu_id > 0 AND (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200) AND ac.entry IS NULL) M ON M.mid = gm.MenuID;
SELECT nt.`ID`, nt.`text0_0`, nt.`text0_1`, nt.`BroadcastTextID0`, nt.`lang0`, nt.`Probability0`, nt.`text1_0`, nt.`text1_1`, nt.`BroadcastTextID1`, nt.`lang1`, nt.`Probability1`, nt.`text2_0`, nt.`text2_1`, nt.`BroadcastTextID2`, nt.`lang2`, nt.`Probability2`, nt.`text3_0`, nt.`text3_1`, nt.`BroadcastTextID3`, nt.`lang3`, nt.`Probability3`, nt.`text4_0`, nt.`text4_1`, nt.`BroadcastTextID4`, nt.`lang4`, nt.`Probability4`, nt.`text5_0`, nt.`text5_1`, nt.`BroadcastTextID5`, nt.`lang5`, nt.`Probability5`, nt.`text6_0`, nt.`text6_1`, nt.`BroadcastTextID6`, nt.`lang6`, nt.`Probability6`, nt.`text7_0`, nt.`text7_1`, nt.`BroadcastTextID7`, nt.`lang7`, nt.`Probability7`, nt.`VerifiedBuild` FROM cata_world.npc_text nt
JOIN (SELECT DISTINCT gm.TextID AS tid FROM cata_world.gossip_menu gm JOIN (SELECT DISTINCT ct.gossip_menu_id AS mid
  FROM cata_world.creature_template ct
  JOIN cata_world.creature c ON c.id = ct.entry
  LEFT JOIN acore_world.creature_template ac ON ac.entry = ct.entry AND ac.entry < @OFF
  WHERE ct.gossip_menu_id > 0 AND (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200) AND ac.entry IS NULL) M ON M.mid = gm.MenuID WHERE gm.TextID>0) T ON T.tid = nt.ID;
SELECT gmo.`MenuID`, gmo.`OptionID`, gmo.`OptionIcon`, gmo.`OptionText`, gmo.`OptionBroadcastTextID`, gmo.`OptionType`, gmo.`OptionNpcFlag`, gmo.`ActionMenuID`, gmo.`ActionPoiID`, gmo.`BoxCoded`, gmo.`BoxMoney`, gmo.`BoxText`, gmo.`BoxBroadcastTextID`, gmo.`VerifiedBuild` FROM cata_world.gossip_menu_option gmo
JOIN (SELECT DISTINCT ct.gossip_menu_id AS mid
  FROM cata_world.creature_template ct
  JOIN cata_world.creature c ON c.id = ct.entry
  LEFT JOIN acore_world.creature_template ac ON ac.entry = ct.entry AND ac.entry < @OFF
  WHERE ct.gossip_menu_id > 0 AND (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200) AND ac.entry IS NULL) M ON M.mid = gmo.MenuID;


-- --- SmartAI  (adapted from 12_smart_scripts.sql) ---
SELECT `entryorguid`+@OFF, `source_type`, `id`, `link`, `event_type`, `event_phase_mask`, `event_chance`, `event_flags`, `event_param1`, `event_param2`, `event_param3`, `event_param4`, `event_param5`, `action_type`, `action_param1`, `action_param2`, `action_param3`, `action_param4`, `action_param5`, `action_param6`, `target_type`, `target_param1`, `target_param2`, `target_x`, `target_y`, `target_z`, `target_o`, `comment` FROM cata_world.smart_scripts WHERE source_type=0 AND entryorguid>0 AND entryorguid IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200)) AND entryorguid NOT IN (SELECT entry FROM acore_world.creature_template WHERE entry < @OFF);
SELECT `entryorguid`+@OFF, `source_type`, `id`, `link`, `event_type`, `event_phase_mask`, `event_chance`, `event_flags`, `event_param1`, `event_param2`, `event_param3`, `event_param4`, `event_param5`, `action_type`, `action_param1`, `action_param2`, `action_param3`, `action_param4`, `action_param5`, `action_param6`, `target_type`, `target_param1`, `target_param2`, `target_x`, `target_y`, `target_z`, `target_o`, `comment` FROM acore_world.smart_scripts WHERE source_type=0 AND entryorguid>0 AND entryorguid IN (SELECT DISTINCT c.id FROM cata_world.creature c WHERE (c.map=1 AND c.zoneId=16 AND c.position_x BETWEEN 3200 AND 5400 AND c.position_y BETWEEN -5334 AND -3200)) AND entryorguid IN (SELECT entry FROM acore_world.creature_template WHERE entry < @OFF) AND entryorguid < @OFF;


DROP TABLE IF EXISTS `_dc_az_mask`;

-- Verify -- expect ~360 creatures / ~240 gameobjects in the corner:
--   SELECT COUNT(*) FROM `creature`   WHERE `map`=750 AND `id`>=3600000
--     AND `position_x` BETWEEN 3200 AND 5400 AND `position_y` BETWEEN -5334 AND -3200;
--   SELECT COUNT(*) FROM `gameobject` WHERE `map`=750 AND `id`>=3600000
--     AND `position_x` BETWEEN 3200 AND 5400 AND `position_y` BETWEEN -5334 AND -3200;
